sys_script_email.script:
(function runMailScript(
    current,
    template,
    email,
    email_action,
    event
) {
    function escapeHtml(value) {
        return String(value || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    var message = event && event.parm2
        ? String(event.parm2)
        : '';

    if (!message) {
        gs.error(
            'EV: mensagem ausente no evento de solicitação ' +
            'de informações para ' + current.getUniqueValue()
        );
        return;
    }

    template.print(
        escapeHtml(message).replace(/\r\n|\r|\n/g, '<br/>')
    );
})(current, template, email, email_action, event);
